1	/**
2	 * SubProcessAdapter — TD-A2 implementation.
3	 *
4	 * Spawns the Claude executor binary as a child process inside the same
5	 * container. Serializes ExecutorInput into environment variables, waits for
6	 * child exit, reads and validates result.json from resultPath.
7	 *
8	 * This is the default ExecutorAdapter wired in main.ts. Future adapters
9	 * (DockerRunAdapter, K8sJobAdapter, QueueProducerAdapter) would implement
10	 * the same interface without touching orchestrator-core code.
11	 */
12	
13	import { spawn } from "node:child_process";
14	import { readFileSync, existsSync } from "node:fs";
15	import { join } from "node:path";
16	import type { ExecutorAdapter, ExecutorInput, ExecutorResult } from "@workflow/runtime-abi";
17	import { validateResult } from "@workflow/runtime-abi";
18	
19	function emit(event: Record<string, unknown>): void {
20	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
21	}
22	
23	export interface SubProcessAdapterOpts {
24	  /**
25	   * Path to the executor entrypoint JS file.
26	   * Defaults to the sibling executor binary baked into the same container.
27	   */
28	  executorBinPath?: string;
29	  /**
30	   * Maximum wall-clock milliseconds to wait for the executor to exit.
31	   * Defaults to 2 hours (7_200_000 ms).
32	   */
33	  timeoutMs?: number;
34	  /**
35	   * Extra environment variables to pass to the executor process beyond the
36	   * formal ABI env vars. Used for day-1 single-container extras like
37	   * WORKSPACE_ROOT, GIT_AUTHOR_EMAIL, WORKFLOW_LOCAL_PATH, etc.
38	   */
39	  extraEnv?: NodeJS.ProcessEnv;
40	}
41	
42	export class SubProcessAdapter implements ExecutorAdapter {
43	  private readonly executorBinPath: string;
44	  private readonly timeoutMs: number;
45	  private readonly extraEnv: NodeJS.ProcessEnv;
46	
47	  constructor(opts: SubProcessAdapterOpts = {}) {
48	    this.executorBinPath =
49	      opts.executorBinPath ??
50	      join(
51	        // The executor binary is baked into the Docker image at /workflow/...
52	        // WORKFLOW_LOCAL_PATH points to the git-clone volume (/agent/workflow) and
53	        // must NOT be used here — those are two separate paths inside the container.
54	        process.env.EXECUTOR_BIN_PREFIX ?? "/workflow",
55	        "runtime",
56	        "executors",
57	        "claude",
58	        "dist",
59	        "index.js",
60	      );
61	    this.timeoutMs = opts.timeoutMs ?? 7_200_000;
62	    this.extraEnv = opts.extraEnv ?? {};
63	  }
64	
65	  async run(input: ExecutorInput): Promise<ExecutorResult> {
66	    const {
67	      taskId,
68	      featureId,
69	      workspaceId,
70	      taskRepoUrl,
71	      taskRepoBranch,
72	      taskRepoPath,
73	      briefingPath,
74	      resultPath,
75	      budgetTokens,
76	      sshPrivateKey,
77	      githubToken,
78	    } = input;
79	
80	    const childEnv: NodeJS.ProcessEnv = {
81	      ...process.env,
82	      ...this.extraEnv,
83	      // Formal ABI env vars
84	      TASK_ID: taskId,
85	      FEATURE_ID: featureId,
86	      WORKSPACE_ID: workspaceId,
87	      TASK_REPO_URL: taskRepoUrl,
88	      TASK_REPO_BRANCH: taskRepoBranch,
89	      TASK_REPO_PATH: taskRepoPath,
90	      BRIEFING_PATH: briefingPath,
91	      RESULT_PATH: resultPath,
92	      GITHUB_TOKEN: githubToken,
93	      ...(sshPrivateKey ? { SSH_PRIVATE_KEY: sshPrivateKey } : {}),
94	      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
95	    };
96	
97	    emit({
98	      type: "executor_spawn",
99	      task_id: taskId,
100	      feature_id: featureId,
101	      bin: this.executorBinPath,
102	    });
103	
104	    const { status, error } = await new Promise<{
105	      status: number | null;
106	      signal: string | null;
107	      error?: Error;
108	    }>((resolve) => {
109	      const child = spawn("node", [this.executorBinPath], {
110	        env: childEnv,
111	        stdio: "inherit",
112	      });
113	
114	      let watchdog: ReturnType<typeof setTimeout> | null = null;
115	      watchdog = setTimeout(() => {
116	        if (!child.killed) {
117	          emit({ type: "executor_timeout", task_id: taskId, feature_id: featureId, timeout_ms: this.timeoutMs });
118	          child.kill("SIGTERM");
119	        }
120	      }, this.timeoutMs);
121	
122	      child.on("error", (err: Error) => {
123	        if (watchdog !== null) clearTimeout(watchdog);
124	        resolve({ status: null, signal: null, error: err });
125	      });
126	
127	      child.on("close", (code: number | null, signal: string | null) => {
128	        if (watchdog !== null) clearTimeout(watchdog);
129	        resolve({ status: code, signal });
130	      });
131	    });
132	
133	    emit({
134	      type: "executor_exit",
135	      task_id: taskId,
136	      feature_id: featureId,
137	      exit_code: status,
138	    });
139	
140	    if (error) {
141	      return {
142	        terminal_status: "failed",
143	        blocked_reason: `executor_spawn_error: ${error.message}`,
144	      };
145	    }
146	
147	    // ── Read result.json ──────────────────────────────────────────────────────
148	    if (!existsSync(resultPath)) {
149	      const reason =
150	        status !== 0 && status !== null
151	          ? `executor_crashed (exit ${status})`
152	          : "no_result_file";
153	      return {
154	        terminal_status: "failed",
155	        blocked_reason: reason,
156	      };
157	    }
158	
159	    let raw: unknown;
160	    try {
161	      raw = JSON.parse(readFileSync(resultPath, "utf-8"));
162	    } catch (e) {
163	      return {
164	        terminal_status: "failed",
165	        blocked_reason: `result_parse_error: ${String(e)}`,
166	      };
167	    }
168	
169	    const validation = validateResult(raw);
170	    if (!validation.valid) {
171	      return {
172	        terminal_status: "failed",
173	        blocked_reason: `result_schema_invalid: ${validation.errors?.join("; ")}`,
174	      };
175	    }
176	
177	    return raw as ExecutorResult;
178	  }
179	}
