1	/**
2	 * T4: Draft-state comment resolution dispatch.
3	 *
4	 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
5	 *
6	 *   1. Claims the review work by appending a `review_started` log entry to
7	 *      the task YAML on the management-repo feature branch and pushing.
8	 *      First-push-wins: if the push is rejected, another agent claimed first.
9	 *
10	 *   2. Generates a review briefing that instructs Claude to execute the
11	 *      `respond-to-review` skill.
12	 *
13	 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
14	 */
15	
16	import { execSync, spawnSync } from "node:child_process";
17	import { join } from "node:path";
18	import { tmpdir } from "node:os";
19	import { randomUUID } from "node:crypto";
20	import type { Task } from "../types/task.js";
21	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
22	import { buildGitEnv } from "../git-env.js";
23	import { SubProcessAdapterW2 } from "../adapters/executor/subprocess.js";
24	import type { ExecutorPortInput, CompletionBrokerPort } from "@workflow/runtime-abi";
25	import { taskYamlRelPath } from "../paths.js";
26	import { readTask, writeTask } from "../utils/task-yaml-io.js";
27	import { writeBriefing } from "../briefing/write-briefing.js";
28	import { preambleSection, identitySection, taskContextSection, modelSection, joinSections } from "../briefing/briefing-template.js";
29	
30	// ── Public types ──────────────────────────────────────────────────────────────
31	
32	export type DraftReviewOutcome =
33	  | "claim_lost"
34	  | "dispatched";
35	
36	export interface DispatchOneReviewOptions {
37	  workspaceRoot: string;
38	  featureId: string;
39	  taskId: string;
40	  taskBranch: string;
41	  implRepoRoot: string;
42	  /** SSH or HTTPS URL of the implementation repo. */
43	  implRepoUrl: string;
44	  gitAuthorEmail: string;
45	  gitAuthorName?: string;
46	  sshKeyPath?: string;
47	  workflowLocalPath: string;
48	  maxTurns: number;
49	  maxTokens: number;
50	  logSinkEnabled: boolean;
51	  implementationModel: string;
52	  workspaceId: string;
53	  githubToken: string;
54	  /** Completion broker for async submit. */
55	  broker: CompletionBrokerPort;
56	  /** Callback URL the runner wrapper will POST to. Pre-computed by caller. */
57	  callbackUrl: string;
58	  emit: (event: Record<string, unknown>) => void;
59	}
60	
61	export interface HandleDraftReviewsOptions {
62	  prResults: PrStatusResult[];
63	  workspaceRoot: string;
64	  resolveImplRepoRoot: (repoId: string) => string;
65	  resolveImplRepoUrl: (repoId: string) => string;
66	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
67	  resolveImplementationModel: (featureId: string, taskId: string) => string;
68	  gitAuthorEmail: string;
69	  gitAuthorName?: string;
70	  sshKeyPath?: string;
71	  workflowLocalPath: string;
72	  maxTurns: number;
73	  maxTokens: number;
74	  logSinkEnabled: boolean;
75	  workspaceId: string;
76	  githubToken: string;
77	  /** Completion broker for async submit. */
78	  broker: CompletionBrokerPort;
79	  /** Callback URL the runner wrapper will POST to. */
80	  callbackUrl: string;
81	  emit: (event: Record<string, unknown>) => void;
82	}
83	
84	// ── Internal helpers ──────────────────────────────────────────────────────────
85	
86	function generateReviewBriefing(opts: {
87	  taskId: string;
88	  featureId: string;
89	  taskTitle: string;
90	  taskBranch: string;
91	  taskRepo: string;
92	  taskRepoRoot: string;
93	  workspaceRoot: string;
94	  prUrl: string;
95	  gitAuthorEmail: string;
96	  gitAuthorName: string;
97	  implementationModel: string;
98	}): string {
99	  const {
100	    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
101	    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
102	  } = opts;
103	
104	  return joinSections(
105	    preambleSection(),
106	    identitySection({ gitAuthorEmail, gitAuthorName }),
107	    taskContextSection("Your claimed task", {
108	      taskId, featureId, taskTitle, taskBranch,
109	      taskRepo, taskRepoRoot, workspaceRoot, prUrl,
110	    }),
111	    [
112	      "## What you must do",
113	      "",
114	      "1. Read the following documents in order to understand the task context before reviewing:",
115	      `   a. \`${workspaceRoot}/docs/features/${featureId}/product-spec.md\` — original user requirements and business constraints`,
116	      `   b. \`${workspaceRoot}/docs/features/${featureId}/technical-design.md\` — implementation approach and architecture`,
117	      `   c. \`${workspaceRoot}/docs/features/${featureId}/tasks.md\` under heading \`## ${taskId} — ${taskTitle}\` — specific task scope and subtasks`,
118	      "2. Run `/respond-to-review` to read and address all open PR review comments,",
119	      "   then convert the PR from draft back to ready-for-review.",
120	      "",
121	      "Complete all steps without stopping or asking for confirmation.",
122	    ],
123	    modelSection(implementationModel),
124	    [
125	      "## Rules",
126	      "",
127	      "- Do not ask clarifying questions.",
128	      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
129	      "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
130	    ],
131	  );
132	}
133	
134	// ── Public API ────────────────────────────────────────────────────────────────
135	
136	export async function dispatchOneReview(
137	  opts: DispatchOneReviewOptions,
138	): Promise<DraftReviewOutcome> {
139	  const {
140	    workspaceRoot,
141	    featureId,
142	    taskId,
143	    taskBranch,
144	    implRepoRoot,
145	    implRepoUrl,
146	    gitAuthorEmail,
147	    gitAuthorName = gitAuthorEmail,
148	    sshKeyPath,
149	    workflowLocalPath,
150	    maxTurns,
151	    maxTokens,
152	    logSinkEnabled,
153	    implementationModel,
154	    workspaceId,
155	    githubToken,
156	    broker,
157	    callbackUrl,
158	    emit,
159	  } = opts;
160	
161	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
162	  const now = new Date().toISOString();
163	
164	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
165	  try {
166	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
167	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
168	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
169	  } catch (e) {
170	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
171	    return "claim_lost";
172	  }
173	
174	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
175	  let task: Task;
176	  try {
177	    task = readTask(workspaceRoot, featureId, taskId);
178	  } catch (e) {
179	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
180	    return "claim_lost";
181	  }
182	
183	  const lastEntry = task.log[task.log.length - 1];
184	  if (lastEntry?.action === "review_started") {
185	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
186	    return "claim_lost";
187	  }
188	
189	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
190	  const MAX_REVIEW_CYCLES = 3;
191	  let consecutiveReviewCycles = 0;
192	  for (let i = task.log.length - 1; i >= 0; i--) {
193	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
194	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
195	  }
196	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
197	    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
198	    return "claim_lost";
199	  }
200	
201	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
202	  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
203	  task.execution.last_updated_by = gitAuthorEmail;
204	  task.execution.last_updated_at = now;
205	  writeTask(workspaceRoot, featureId, task);
206	
207	  const relPath = taskYamlRelPath(featureId, taskId);
208	  try {
209	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
210	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
211	  } catch (e) {
212	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
213	    return "claim_lost";
214	  }
215	
216	  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
217	    env, encoding: "utf-8",
218	  });
219	  if (claimPush.status !== 0) {
220	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
221	    return "claim_lost";
222	  }
223	
224	  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });
225	
226	  // ── 4. Build review briefing and submit executor (async — T6) ────────────────
227	  const reviewBriefing = generateReviewBriefing({
228	    taskId,
229	    featureId,
230	    taskTitle: task.title,
231	    taskBranch,
232	    taskRepo: task.repo,
233	    taskRepoRoot: implRepoRoot,
234	    workspaceRoot,
235	    prUrl: task.pr.url,
236	    gitAuthorEmail,
237	    gitAuthorName,
238	    implementationModel,
239	  });
240	
241	  const { briefingPath } = writeBriefing({ taskId, briefingContent: reviewBriefing });
242	
243	  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
244	  const nonce = randomUUID();
245	
246	  const input: ExecutorPortInput = {
247	    taskId,
248	    featureId,
249	    workspaceId,
250	    taskRepoUrl: implRepoUrl,
251	    taskRepoBranch: taskBranch,
252	    taskRepoPath: implRepoRoot,
253	    briefingPath,
254	    resultPath,
255	    budgetTokens: maxTokens,
256	    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
257	    githubToken,
258	    callbackUrl,
259	    nonce,
260	  };
261	
262	  const reviewAdapter = new SubProcessAdapterW2({
263	    broker,
264	    extraEnv: {
265	      WORKSPACE_ROOT: workspaceRoot,
266	      TASK_BRANCH: taskBranch,
267	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
268	      GIT_AUTHOR_NAME: gitAuthorName,
269	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
270	      MAX_TURNS: String(maxTurns),
271	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
272	    },
273	  });
274	
275	  const handle = await reviewAdapter.submit(input);
276	
277	  emit({
278	    type: "review_submitted",
279	    task_id: taskId,
280	    feature_id: featureId,
281	    handle,
282	  });
283	
284	  return "dispatched";
285	}
286	
287	export async function handleDraftReviews(
288	  opts: HandleDraftReviewsOptions,
289	): Promise<void> {
290	  const {
291	    prResults,
292	    workspaceRoot,
293	    resolveImplRepoRoot,
294	    resolveImplRepoUrl,
295	    resolveTaskRepoId,
296	    resolveImplementationModel,
297	    gitAuthorEmail,
298	    gitAuthorName,
299	    sshKeyPath,
300	    workflowLocalPath,
301	    maxTurns,
302	    maxTokens,
303	    logSinkEnabled,
304	    workspaceId,
305	    githubToken,
306	    broker,
307	    callbackUrl,
308	    emit,
309	  } = opts;
310	
311	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
312	
313	  for (const result of draftTasks) {
314	    const { taskId, featureId } = result;
315	
316	    let repoId: string;
317	    try {
318	      repoId = resolveTaskRepoId(featureId, taskId);
319	    } catch (e) {
320	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
321	      continue;
322	    }
323	
324	    let implRepoRoot: string;
325	    let implRepoUrl: string;
326	    try {
327	      implRepoRoot = resolveImplRepoRoot(repoId);
328	      implRepoUrl = resolveImplRepoUrl(repoId);
329	    } catch (e) {
330	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
331	      continue;
332	    }
333	
334	    let implementationModel: string;
335	    try {
336	      implementationModel = resolveImplementationModel(featureId, taskId);
337	    } catch (e) {
338	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
339	      continue;
340	    }
341	
342	    const taskBranch = `feature/${featureId}-${taskId}`;
343	
344	    try {
345	      await dispatchOneReview({
346	        workspaceRoot,
347	        featureId,
348	        taskId,
349	        taskBranch,
350	        implRepoRoot,
351	        implRepoUrl,
352	        gitAuthorEmail,
353	        gitAuthorName,
354	        sshKeyPath,
355	        workflowLocalPath,
356	        maxTurns,
357	        maxTokens,
358	        logSinkEnabled,
359	        implementationModel,
360	        workspaceId,
361	        githubToken,
362	        broker,
363	        callbackUrl,
364	        emit,
365	      });
366	    } catch (e) {
367	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
368	    }
369	  }
370	}
