1	/**
2	 * SubProcessAdapterW2 — ExecutorPort adapter (Wave 3 / T5).
3	 *
4	 * Wave 3 version implements the async runner-callback shape:
5	 *  - submit() registers the handle with the broker, then spawns the runner
6	 *    wrapper (T4) as a detached child. Returns the handle immediately without
7	 *    waiting for the executor to finish.
8	 *  - Completion arrives via HTTP callback: runner POSTs { handle, nonce, result }
9	 *    to the broker's /callback endpoint; the orchestrator drains via
10	 *    broker.listCompleted (T6).
11	 *  - readResult() is a no-op for this profile — result rides in the callback.
12	 *  - ack() removes the handle from the supervision map, cleans up the result
13	 *    file, and delegates to broker.ack.
14	 *
15	 * Runner-supervision map:
16	 *   Keyed by handle; stores (pid, startedAt, nonce, callbackUrl, resultPath).
17	 *   Purpose: the wrapper-crash safety net only — not in-flight state (the
18	 *   broker owns that). On child.on('exit'), a grace timer fires; if the
19	 *   handle is still in the supervision map when the timer fires, the adapter
20	 *   POSTs a synthetic "failed" completion to the broker on the runner's behalf.
21	 *
22	 * Backward compatibility:
23	 *   The existing SubProcessAdapter in adapter/spawn.ts (ExecutorAdapter) is
24	 *   preserved unchanged for backward compatibility with existing seam tests.
25	 */
26	
27	import { randomUUID } from "node:crypto";
28	import { spawn } from "node:child_process";
29	import { unlinkSync } from "node:fs";
30	import * as http from "node:http";
31	import * as https from "node:https";
32	import { join } from "node:path";
33	import type {
34	  ExecutorPort,
35	  ExecutorPortInput,
36	  ExecutorHandle,
37	  ExecutorResult,
38	  CompletionBrokerPort,
39	} from "@workflow/runtime-abi";
40	
41	// ── Types ─────────────────────────────────────────────────────────────────────
42	
43	export interface SubProcessAdapterOpts {
44	  /**
45	   * Path to runner.js (the platform-owned wrapper script from T4).
46	   * Defaults to the standard location baked into the container image.
47	   */
48	  runnerBinPath?: string;
49	
50	  /**
51	   * Path to the executor binary. Passed as EXECUTOR_BIN env var to the
52	   * runner wrapper so it knows what to exec. Defaults to the standard
53	   * container location; override in tests.
54	   */
55	  executorBinPath?: string;
56	
57	  /**
58	   * Maximum wall-clock milliseconds before the watchdog kills the runner.
59	   * Defaults to 2 hours (7_200_000 ms).
60	   */
61	  timeoutMs?: number;
62	
63	  /**
64	   * Extra environment variables passed to the runner wrapper (and inherited
65	   * by the executor). Used for day-1 single-container extras like
66	   * WORKSPACE_ROOT, GIT_AUTHOR_EMAIL, WORKFLOW_LOCAL_PATH, etc.
67	   */
68	  extraEnv?: NodeJS.ProcessEnv;
69	
70	  /**
71	   * CompletionBrokerPort instance. Required for the full async callback flow.
72	   * If absent, broker.register is skipped and the adapter operates in
73	   * broker-less mode (useful for isolated unit tests).
74	   */
75	  broker?: CompletionBrokerPort;
76	
77	  /**
78	   * Grace window (ms) after child.on('exit') before the safety-net synthetic
79	   * failure is posted to the broker. This allows a callback that was in-flight
80	   * at crash time to arrive before we synthesize a failure.
81	   * Default: 5 000 ms.
82	   */
83	  crashGraceMs?: number;
84	}
85	
86	interface SupervisionEntry {
87	  pid: number;
88	  startedAt: string; // ISO 8601
89	  nonce: string;
90	  callbackUrl: string;
91	  resultPath: string;
92	  taskId: string;
93	  featureId: string;
94	}
95	
96	// ── Defaults ──────────────────────────────────────────────────────────────────
97	
98	const DEFAULT_RUNNER_BIN = join(
99	  process.env.EXECUTOR_BIN_PREFIX ?? "/workflow",
100	  "runtime",
101	  "runner-wrapper",
102	  "runner.js",
103	);
104	
105	const DEFAULT_TIMEOUT_MS = 7_200_000;
106	const DEFAULT_CRASH_GRACE_MS = 5_000;
107	
108	// ── Helpers ───────────────────────────────────────────────────────────────────
109	
110	function emit(event: Record<string, unknown>): void {
111	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
112	}
113	
114	/** HTTP POST for the safety-net synthetic failure. Resolves regardless of status. */
115	function _httpPost(url: string, body: string): Promise<void> {
116	  return new Promise((resolve, reject) => {
117	    let u: URL;
118	    try {
119	      u = new URL(url);
120	    } catch {
121	      reject(new Error(`_httpPost: invalid URL: ${url}`));
122	      return;
123	    }
124	    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
125	    const req = lib.request(
126	      {
127	        hostname: u.hostname,
128	        port: u.port || (u.protocol === "https:" ? 443 : 80),
129	        path: u.pathname + u.search,
130	        method: "POST",
131	        headers: {
132	          "Content-Type": "application/json",
133	          "Content-Length": Buffer.byteLength(body),
134	        },
135	      },
136	      (res) => {
137	        res.resume(); // drain the response
138	        resolve();
139	      },
140	    );
141	    req.on("error", reject);
142	    req.write(body);
143	    req.end();
144	  });
145	}
146	
147	// ── SubProcessAdapterW2 ───────────────────────────────────────────────────────
148	
149	export class SubProcessAdapterW2 implements ExecutorPort {
150	  private readonly runnerBinPath: string;
151	  private readonly executorBinPath: string | undefined;
152	  private readonly timeoutMs: number;
153	  private readonly extraEnv: NodeJS.ProcessEnv;
154	  private readonly broker: CompletionBrokerPort | null;
155	  private readonly crashGraceMs: number;
156	
157	  /** Keyed by handle; tracks in-flight runners for the safety-net sweep. */
158	  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();
159	
160	  constructor(opts: SubProcessAdapterOpts = {}) {
161	    this.runnerBinPath = opts.runnerBinPath ?? DEFAULT_RUNNER_BIN;
162	    this.executorBinPath = opts.executorBinPath;
163	    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
164	    this.extraEnv = opts.extraEnv ?? {};
165	    this.broker = opts.broker ?? null;
166	    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
167	  }
168	
169	  // ── ExecutorPort ─────────────────────────────────────────────────────────
170	
171	  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
172	    const {
173	      taskId,
174	      featureId,
175	      workspaceId,
176	      taskRepoUrl,
177	      taskRepoBranch,
178	      taskRepoPath,
179	      briefingPath,
180	      resultPath,
181	      budgetTokens,
182	      sshPrivateKey,
183	      githubToken,
184	      callbackUrl,
185	      nonce,
186	    } = input;
187	
188	    const handle = randomUUID();
189	    const startedAt = new Date().toISOString();
190	
191	    // 1. Register handle with broker before spawning (broker must record it
192	    //    before the runner can POST back, else the callback arrives at an
193	    //    unregistered handle and is rejected 401).
194	    if (this.broker) {
195	      await this.broker.register(handle, nonce, {
196	        kind: "impl",
197	        task_id: taskId,
198	        feature_id: featureId,
199	        started_at: startedAt,
200	      });
201	    }
202	
203	    // 2. Build environment for the runner wrapper (and inherited by executor).
204	    const childEnv: NodeJS.ProcessEnv = {
205	      ...process.env,
206	      ...this.extraEnv,
207	      // Formal ABI env vars — passed through to the executor
208	      TASK_ID: taskId,
209	      FEATURE_ID: featureId,
210	      WORKSPACE_ID: workspaceId,
211	      TASK_REPO_URL: taskRepoUrl,
212	      TASK_REPO_BRANCH: taskRepoBranch,
213	      TASK_REPO_PATH: taskRepoPath,
214	      BRIEFING_PATH: briefingPath,
215	      RESULT_PATH: resultPath,
216	      GITHUB_TOKEN: githubToken,
217	      ...(sshPrivateKey ? { SSH_PRIVATE_KEY: sshPrivateKey } : {}),
218	      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
219	      // Runner wrapper contract (T-Q10)
220	      CALLBACK_URL: callbackUrl,
221	      HANDLE: handle,
222	      NONCE: nonce,
223	      ...(this.executorBinPath ? { EXECUTOR_BIN: this.executorBinPath } : {}),
224	    };
225	
226	    emit({
227	      type: "executor_spawn",
228	      task_id: taskId,
229	      feature_id: featureId,
230	      handle,
231	      runner: this.runnerBinPath,
232	    });
233	
234	    // 3. Spawn runner wrapper — non-blocking; returns immediately.
235	    const child = spawn("node", [this.runnerBinPath], {
236	      env: childEnv,
237	      stdio: "inherit",
238	      detached: false,
239	    });
240	
241	    // 4. Track in supervision map.
242	    this.supervision.set(handle, {
243	      pid: child.pid ?? 0,
244	      startedAt,
245	      nonce,
246	      callbackUrl,
247	      resultPath,
248	      taskId,
249	      featureId,
250	    });
251	
252	    // 5. Watchdog: kill runner if it exceeds the wall-clock timeout.
253	    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
254	      watchdog = null;
255	      if (!child.killed) {
256	        emit({
257	          type: "executor_timeout",
258	          task_id: taskId,
259	          feature_id: featureId,
260	          handle,
261	          timeout_ms: this.timeoutMs,
262	        });
263	        child.kill("SIGTERM");
264	      }
265	    }, this.timeoutMs);
266	    // Don't hold the event loop open for the watchdog.
267	    if (watchdog.unref) watchdog.unref();
268	
269	    // 6. Safety net: if the runner exits without the broker receiving a
270	    //    callback within crashGraceMs, synthesize a "failed" completion.
271	    child.on("exit", (code, signal) => {
272	      if (watchdog !== null) {
273	        clearTimeout(watchdog);
274	        watchdog = null;
275	      }
276	
277	      emit({
278	        type: "executor_exit",
279	        task_id: taskId,
280	        feature_id: featureId,
281	        handle,
282	        exit_code: code,
283	        signal,
284	      });
285	
286	      const graceTimer = setTimeout(() => {
287	        if (!this.supervision.has(handle)) return; // already acked
288	        const entry = this.supervision.get(handle)!;
289	        this.supervision.delete(handle);
290	
291	        if (!entry.callbackUrl) return; // no callback URL to POST to
292	
293	        const reason = signal
294	          ? `runner_killed_by_signal: ${signal}`
295	          : code !== null && code !== 0
296	            ? `runner_crashed (exit ${code})`
297	            : "runner_no_callback";
298	
299	        emit({
300	          type: "executor_safety_net",
301	          task_id: entry.taskId,
302	          feature_id: entry.featureId,
303	          handle,
304	          reason,
305	        });
306	
307	        const body = JSON.stringify({
308	          handle,
309	          nonce: entry.nonce,
310	          result: { terminal_status: "failed", blocked_reason: reason },
311	        });
312	
313	        _httpPost(entry.callbackUrl, body).catch(() => {
314	          // Best-effort — ignore POST failures in the safety net.
315	        });
316	      }, this.crashGraceMs);
317	
318	      // Don't hold the event loop open for the grace timer.
319	      if (graceTimer.unref) graceTimer.unref();
320	    });
321	
322	    return handle;
323	  }
324	
325	  /**
326	   * Wave 3: result arrives via broker callback — readResult is a no-op for
327	   * this profile. Returns a "failed / handle_not_found" tombstone so callers
328	   * that mistakenly poll readResult get a predictable signal.
329	   */
330	  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
331	    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
332	  }
333	
334	  // ── Supervision helpers ───────────────────────────────────────────────────
335	
336	  /**
337	   * Acknowledge a completed handle:
338	   *  - Removes the entry from the supervision map (disarms the safety net).
339	   *  - Deletes the temp result file written by the executor.
340	   *  - Delegates to broker.ack to commit consumption in the broker.
341	   *
342	   * Call this after the orchestrator has successfully processed the completion
343	   * returned by broker.listCompleted.
344	   */
345	  async ack(handle: ExecutorHandle): Promise<void> {
346	    const entry = this.supervision.get(handle);
347	    if (entry) {
348	      this.supervision.delete(handle);
349	      try {
350	        unlinkSync(entry.resultPath);
351	      } catch {
352	        // Best-effort — file may already be gone.
353	      }
354	    }
355	    if (this.broker) {
356	      await this.broker.ack(handle);
357	    }
358	  }
359	
360	  /** Number of handles currently tracked in the supervision map. */
361	  supervisionSize(): number {
362	    return this.supervision.size;
363	  }
364	}
