1	/**
2	 * T4: Draft-state comment resolution dispatch.
3	 *
4	 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
5	 *
6	 *   1. Claims the review work by appending a `review_started` log entry to
7	 *      the task YAML on the management-repo feature branch and pushing.
8	 *      First-push-wins: if the push is rejected, another agent claimed first.
9	 *
10	 *   2. Generates a review briefing that instructs Claude to execute the
11	 *      `respond-to-review` skill.
12	 *
13	 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
14	 */
15	
16	import { execSync, spawnSync } from "node:child_process";
17	import { join } from "node:path";
18	import { tmpdir } from "node:os";
19	import { randomUUID } from "node:crypto";
20	import type { Task } from "../types/task.js";
21	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
22	import { buildGitEnv } from "../git-env.js";
23	import { SubProcessAdapterW2 } from "../adapters/executor/subprocess.js";
24	import type { ExecutorPortInput, CompletionBrokerPort } from "@workflow/runtime-abi";
25	import { taskYamlRelPath } from "../paths.js";
26	import { readTask, writeTask } from "../utils/task-yaml-io.js";
27	import { writeBriefing } from "../briefing/write-briefing.js";
28	import { preambleSection, identitySection, taskContextSection, modelSection, joinSections } from "../briefing/briefing-template.js";
29	
30	// ── Public types ──────────────────────────────────────────────────────────────
31	
32	export type DraftReviewOutcome =
33	  | "claim_lost"
34	  | "dispatched";
35	
36	export interface DispatchOneReviewOptions {
37	  workspaceRoot: string;
38	  featureId: string;
39	  taskId: string;
40	  taskBranch: string;
41	  implRepoRoot: string;
42	  /** SSH or HTTPS URL of the implementation repo. */
43	  implRepoUrl: string;
44	  gitAuthorEmail: string;
45	  gitAuthorName?: string;
46	  sshKeyPath?: string;
