/**
 * local-subprocess profile factory.
 *
 * Bundles the Wave-3 adapter set into a RuntimePorts instance for the
 * single-container, single-process topology: orchestrator and executor
 * run as child processes inside the same image.
 *
 * Adapter set:
 *   ExecutorPort         → SubProcessAdapterW2     (blocks in Wave 2; async in Wave 3/T5)
 *   CompletionBrokerPort → InMemoryBrokerAdapter   (Wave 3 / T3 — embedded HTTP receiver)
 *   BriefingTransport    → LocalFileBriefingAdapter
 *   WorkflowState        → GitWorkflowStateAdapter
 *   Credential           → EnvCredentialAdapter
 *   WorkspacePull        → GitClonePullAdapter
 *   EventEmitter         → StdoutJsonEmitter
 *   Scheduler            → SimpleSleepScheduler
 *   Clock                → RealClock
 */

import type { RuntimePorts } from "../runtime-ports.js";
import { SubProcessAdapterW2, type SubProcessAdapterOpts } from "../adapters/executor/subprocess.js";
import { InMemoryBrokerAdapter, type InMemoryBrokerAdapterOpts } from "../adapters/broker/in-memory.js";
import { LocalFileBriefingAdapter } from "../adapters/briefing/local-file.js";
import { GitWorkflowStateAdapter } from "../adapters/workflow-state/git.js";
import { EnvCredentialAdapter } from "../adapters/credential/env.js";
import { GitClonePullAdapter } from "../adapters/workspace-pull/git-clone-pull.js";
import { StdoutJsonEmitter } from "../adapters/emitter/stdout-json.js";
import { SimpleSleepScheduler } from "../adapters/scheduler/simple-sleep.js";
import { RealClock } from "../adapters/clock/real.js";

export interface LocalSubprocessProfileOpts {
  /** Options forwarded to SubProcessAdapterW2. */
  executor?: SubProcessAdapterOpts;
  /** Options forwarded to InMemoryBrokerAdapter. */
  broker?: InMemoryBrokerAdapterOpts;
  /** Git identity for WorkflowStatePort operations. */
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/** The broker is part of the profile bundle so callers can call start()/stop(). */
export interface LocalSubprocessProfileBundle extends RuntimePorts {
  broker: InMemoryBrokerAdapter;
}

/**
 * Create a RuntimePorts bundle wired for the local-subprocess profile.
 *
 * Callers must call `bundle.broker.start()` after creation to bind the HTTP
 * receiver port, and `bundle.broker.stop()` on graceful shutdown.
 *
 * The broker is wired into the executor so that SubProcessAdapterW2.submit()
 * can call broker.register() before spawning the runner wrapper (T5 Wave-3).
 * The orchestrator then passes callbackUrl = broker.getCallbackUrl() in the
 * ExecutorPortInput when submitting tasks.
 *
 * Example:
 *   const bundle = createLocalSubprocessProfile({ gitAuthorEmail: '...' });
 *   const brokerPort = await bundle.broker.start();
 *   // pass bundle to orchestrator concerns...
 *   await bundle.broker.stop();
 */
export function createLocalSubprocessProfile(
  opts: LocalSubprocessProfileOpts,
): LocalSubprocessProfileBundle {
  const broker = new InMemoryBrokerAdapter(opts.broker);
  const executor = new SubProcessAdapterW2({ ...opts.executor, broker });
  return {
    executor,
    broker,
    briefing: new LocalFileBriefingAdapter(),
    workflowState: new GitWorkflowStateAdapter({
      gitAuthorEmail: opts.gitAuthorEmail,
      gitAuthorName: opts.gitAuthorName,
      sshKeyPath: opts.sshKeyPath,
    }),
    credential: new EnvCredentialAdapter(),
    workspacePull: new GitClonePullAdapter(),
    emitter: new StdoutJsonEmitter(),
    scheduler: new SimpleSleepScheduler(),
    clock: new RealClock(),
  };
}

