/**
 * Tests for pr-response/dispatch-draft-review.ts
 *
 * Unit tests only — no real git operations or Claude spawns. `execSync` and
 * `spawnSync` are mocked via vi.mock. SubProcessAdapterW2 is mocked to avoid
 * subprocess spawning. Filesystem operations use real temp directories.
 *
 * T6 changes: dispatchOneReview now uses SubProcessAdapterW2.submit() (async,
 * non-blocking) instead of SubProcessAdapter.run() (blocking). The function
 * emits "review_submitted" (handle submitted) rather than "review_dispatch_complete"
 * (result received). The reap loop emits the completion event when the runner
 * POSTs its result back to the broker.
 *
 * Covers:
 *   1. dispatchOneReview — claim_lost when checkout of task branch fails
 *   2. dispatchOneReview — claim_lost when task log already has review_started
 *   3. dispatchOneReview — claim_lost when push of claim commit is rejected
 *   4. dispatchOneReview — dispatched on successful claim + async submit
 *   5. handleDraftReviews — only processes tasks with hasOpenComments === true
 *   6. handleDraftReviews — skips all tasks when none have hasOpenComments === true
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import type { PrStatusResult } from "../src/poll/check-in-review-prs.js";
import {
  dispatchOneReview,
  handleDraftReviews,
  type DispatchOneReviewOptions,
  type HandleDraftReviewsOptions,
} from "../src/pr-response/dispatch-draft-review.js";
import { FakeBrokerAdapter } from "@workflow/runtime-abi";

// ── Mock node:child_process ───────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual =
    await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Mock SubProcessAdapterW2 (T6: async submit) ───────────────────────────────

vi.mock("../src/adapters/executor/subprocess.js", () => ({
  SubProcessAdapterW2: vi.fn().mockImplementation(() => ({
    submit: vi.fn().mockResolvedValue("fake-review-handle"),
  })),
}));

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T4";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "agent@test.com";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Draft Review Task",
    repo: "impl-repo",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: GIT_AUTHOR_EMAIL,
      last_updated_at: "2026-04-19T00:00:00Z",
    },
    pr: {
      url: "https://github.com/myorg/impl-repo/pull/42",
      status: "open",
    },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task, featureId = FEATURE_ID): string {
  const dir = mkdtempSync(join(tmpdir(), "dispatch-draft-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");

/**
 * Seam tests: orchestrator dispatch + FakeAdapter / SubProcessAdapter.
 *
 * These tests exercise the ABI seam — the boundary between the adapter
 * (which produces an ExecutorResult) and the orchestrator's side-effect
 * dispatcher (which translates that result into task YAML mutations).
 *
 * Uses dispatchExecutorResult (extracted from main.ts) so the full
 * bootstrap + poll loop does not need to run.
 *
 * Revised D5: the executor owns impl-PR creation; the orchestrator only
 * records the pr_url reported in result.json. No curl/GitHub API calls are
 * made by the orchestrator for impl PRs.
 *
 * FakeAdapter scenarios:
 *   1. in_review with pr_url → task in_review, pr.url recorded, no GitHub API call
 *   2. in_review without pr_url → task in_review, no pr.url set
 *   3. blocked with pr_url → task blocked, pr.url still recorded (draft PR)
 *   4. blocked with reason + suggestion → task marked blocked
 *   5. failed with executor_crashed reason → task blocked with executor_failed prefix
 *   6. failed with result_schema_invalid reason → task blocked with executor_failed prefix
 *
 * SubProcessAdapter scenarios:
 *   7. wall-clock timeout (short timeout + hanging subprocess) → task blocked (failed result)
 *   8. executor non-zero exit (no result.json) → returns failed with executor_crashed
 *   9. schema-invalid result.json → returns failed with result_schema_invalid
 */

