/**
 * Seam tests: orchestrator dispatch + FakeAdapter / SubProcessAdapter.
 *
 * These tests exercise the ABI seam — the boundary between the adapter
 * (which produces an ExecutorResult) and the orchestrator's side-effect
 * dispatcher (which translates that result into task YAML mutations).
 *
 * Uses dispatchExecutorResult (extracted from main.ts) so the full
 * bootstrap + poll loop does not need to run.
 *
 * Revised D5: the executor owns impl-PR creation; the orchestrator only
 * records the pr_url reported in result.json. No curl/GitHub API calls are
 * made by the orchestrator for impl PRs.
 *
 * FakeAdapter scenarios:
 *   1. in_review with pr_url → task in_review, pr.url recorded, no GitHub API call
 *   2. in_review without pr_url → task in_review, no pr.url set
 *   3. blocked with pr_url → task blocked, pr.url still recorded (draft PR)
 *   4. blocked with reason + suggestion → task marked blocked
 *   5. failed with executor_crashed reason → task blocked with executor_failed prefix
 *   6. failed with result_schema_invalid reason → task blocked with executor_failed prefix
 *
 * SubProcessAdapter scenarios:
 *   7. wall-clock timeout (short timeout + hanging subprocess) → task blocked (failed result)
 *   8. executor non-zero exit (no result.json) → returns failed with executor_crashed
 *   9. schema-invalid result.json → returns failed with result_schema_invalid
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import {
  createFakeAdapter,
  createInReviewAdapter,
  createBlockedAdapter,
  createFailedAdapter,
} from "@workflow/runtime-abi";
import type { ExecutorInput } from "@workflow/runtime-abi";
import { SubProcessAdapter } from "../src/adapter/spawn.js";
import { dispatchExecutorResult } from "../src/side-effects/dispatch.js";

// ── Mock git for dispatch side-effects ────────────────────────────────────────

