/**
 * Seam tests: orchestrator dispatch + FakeAdapter.
 *
 * These tests exercise the ABI seam — the boundary between the adapter
 * (which produces an ExecutorResult) and the orchestrator's side-effect
 * dispatcher (which translates that result into task YAML mutations).
 *
 * Uses dispatchExecutorResult (extracted from main.ts) so the full
 * bootstrap + poll loop does not need to run.
 *
 * Revised D5: the executor owns impl-PR creation; the orchestrator only
 * records the pr_url reported in result.json. No curl/GitHub API calls are
 * made by the orchestrator for impl PRs.
 *
 * FakeAdapter scenarios:
 *   1. in_review with pr_url → task in_review, pr.url recorded, no GitHub API call
 *   2. in_review without pr_url → task in_review, no pr.url set
 *   3. blocked with pr_url → task blocked, pr.url still recorded (draft PR)
 *   4. blocked with reason + suggestion → task marked blocked
 *   5. failed with executor_crashed reason → task blocked with executor_failed prefix
 *   6. failed with result_schema_invalid reason → task blocked with executor_failed prefix
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import {
  createFakeAdapter,
  createInReviewAdapter,
  createBlockedAdapter,
  createFailedAdapter,
} from "@workflow/runtime-abi";
import { dispatchExecutorResult } from "../src/side-effects/dispatch.js";

// ── Mock git for dispatch side-effects ────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "seam-test-feature";
const TASK_ID = "T1";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const TASK_TITLE = "Seam test task";
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GITHUB_TOKEN = "ghp_test";
const TASK_REPO_URL = "git@github.com:myorg/impl-repo.git";
const TASK_BASE_BRANCH = "main";

const IMPL_PR_URL = "https://github.com/myorg/impl-repo/pull/99";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: TASK_TITLE,
    repo: "impl-repo",
    status: "in_progress",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task): string {
  const dir = mkdtempSync(join(tmpdir(), "seam-dispatch-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  return dir;
}

function readTask(wsRoot: string): Task {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

function mockGitSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
});

const stubInput: ExecutorInput = {
  taskId: TASK_ID,
  featureId: FEATURE_ID,
  workspaceId: "test-workspace",
  taskRepoUrl: TASK_REPO_URL,
  taskRepoBranch: TASK_BRANCH,
  taskRepoPath: "/tmp/impl-repo",
  briefingPath: "/tmp/briefing.md",
  resultPath: "/tmp/result.json",
  sshPrivateKey: "",
  githubToken: GITHUB_TOKEN,
};

// ── 1. in_review with pr_url from result ─────────────────────────────────────

describe("seam: in_review with pr_url in result", () => {
  it("records pr.url from result.pr_url — no GitHub API call made by orchestrator", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("in_review");
    expect(result.pr_url).toBe(IMPL_PR_URL);

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    expect(task.pr.url).toBe(IMPL_PR_URL);
    expect(task.log.some((e) => e.action === "in_review")).toBe(true);

    // Orchestrator emits impl_pr_recorded — not impl_pr_opened (no GitHub API call)
    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(true);
    expect(events.some((e) => e.type === "impl_pr_opened")).toBe(false);

    // No curl calls — orchestrator does not open impl PRs
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── 2. in_review without pr_url ───────────────────────────────────────────────

describe("seam: in_review without pr_url", () => {
  it("task is marked in_review with no pr.url when result carries no pr_url", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createInReviewAdapter();

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("in_review");
    expect(result.pr_url).toBeUndefined();

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: GITHUB_TOKEN,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("in_review");
    // No pr_url in result → pr.url stays empty
    expect(task.pr.url).toBe("");
    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(false);
    // No curl calls
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── 3. blocked with pr_url — draft PR documents failed attempt ────────────────

describe("seam: blocked with pr_url (draft PR)", () => {
  it("records pr.url on blocked task — draft PR documents failed attempt", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "blocked",
      blocked_reason: "tests_failed",
      pr_url: IMPL_PR_URL,
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("blocked");
    expect(result.pr_url).toBe(IMPL_PR_URL);

    const events: Record<string, unknown>[] = [];
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("tests_failed");
    // pr_url recorded even though task is blocked
    expect(task.pr.url).toBe(IMPL_PR_URL);
    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(true);
    // No curl calls
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);
  });
});

// ── 4. blocked with reason + suggestion ──────────────────────────────────────

describe("seam: blocked with reason + suggestion", () => {
  it("FakeAdapter blocked → task status blocked, reason and suggestion written", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createBlockedAdapter("missing_tool", "Install node 20.");

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("blocked");
    expect(result.blocked_reason).toBe("missing_tool");

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("missing_tool");
    expect(task.blocked_suggestion).toBe("Install node 20.");
    expect(task.log.some((e) => e.action === "blocked")).toBe(true);
  });
});

// ── 5. failed → executor_crashed in blocked_reason ───────────────────────────

describe("seam: failed — executor_crashed", () => {
  it("FakeAdapter failed with executor_crashed → task blocked with executor_failed prefix", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "failed",
      blocked_reason: "executor_crashed (exit 1)",
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    expect(result.terminal_status).toBe("failed");

    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(task.blocked_reason).toBe("executor_failed:executor_crashed (exit 1)");
    expect(task.log.some((e) => e.action === "blocked")).toBe(true);
  });
});

// ── 6. failed → result_schema_invalid in blocked_reason ──────────────────────

describe("seam: failed — result_schema_invalid", () => {
  it("FakeAdapter failed with schema reason → task blocked with executor_failed prefix", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const adapter = createFakeAdapter({
      terminal_status: "failed",
      blocked_reason: "result_schema_invalid: must have required property 'terminal_status'",
    });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const result = await adapter.run(stubInput);
    await dispatchExecutorResult({
      result,
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      taskTitle: TASK_TITLE,
      taskRepoUrl: TASK_REPO_URL,
      taskBaseBranch: TASK_BASE_BRANCH,
      githubToken: "",
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: () => {},
    });

    const task = readTask(wsRoot);
    expect(task.status).toBe("blocked");
    expect(String(task.blocked_reason)).toContain("executor_failed:");
    expect(String(task.blocked_reason)).toContain("result_schema_invalid");
  });
});

// ── SubProcessAdapter tests ───────────────────────────────────────────────────
// These tests do NOT use vi.mock for child_process — they spawn real subprocesses.

describe("SubProcessAdapter — executor non-zero exit (no result.json)", () => {
  it("returns failed with executor_crashed when subprocess exits non-zero", async () => {
    vi.restoreAllMocks();

    const resultDir = mkdtempSync(join(tmpdir(), "spawn-result-"));
    tmpDirs.push(resultDir);
    const resultPath = join(resultDir, "result.json");

    const stubDir = mkdtempSync(join(tmpdir(), "spawn-stub-"));
    tmpDirs.push(stubDir);
    const stubPath = join(stubDir, "stub-executor.js");
    writeFileSync(stubPath, "process.exit(1);\n", "utf-8");

    const adapter = new SubProcessAdapter({
      executorBinPath: stubPath,
      timeoutMs: 5_000,
    });

    const result = await adapter.run({
      ...stubInput,
      resultPath,
    });

    expect(result.terminal_status).toBe("failed");
    expect(String(result.blocked_reason)).toMatch(/executor_crashed/);
  }, 15_000);
});

describe("SubProcessAdapter — schema-invalid result.json", () => {
  it("returns failed with result_schema_invalid when result.json fails validation", async () => {
    vi.restoreAllMocks();

    const resultDir = mkdtempSync(join(tmpdir(), "spawn-schema-"));
    tmpDirs.push(resultDir);
    const resultPath = join(resultDir, "result.json");

    const stubDir = mkdtempSync(join(tmpdir(), "spawn-stub-schema-"));
    tmpDirs.push(stubDir);
    const stubPath = join(stubDir, "stub-schema.js");
    writeFileSync(stubPath, [
      `const fs = require("node:fs");`,
      `const resultPath = process.env.RESULT_PATH;`,
      `fs.writeFileSync(resultPath, JSON.stringify({ some_field: "oops" }));`,
      `process.exit(0);`,
    ].join("\n"), "utf-8");

    const adapter = new SubProcessAdapter({
      executorBinPath: stubPath,
      timeoutMs: 5_000,
      extraEnv: { RESULT_PATH: resultPath },
    });

