      resultPath,
    });

    expect(result.terminal_status).toBe("failed");
    expect(String(result.blocked_reason)).toContain("result_schema_invalid");
  }, 15_000);
});

describe("SubProcessAdapter — wall-clock timeout", () => {
  it("kills child and returns failed after timeout expires", async () => {
    vi.restoreAllMocks();

    const resultDir = mkdtempSync(join(tmpdir(), "spawn-timeout-"));
    tmpDirs.push(resultDir);
    const resultPath = join(resultDir, "result.json");

    const stubDir = mkdtempSync(join(tmpdir(), "spawn-stub-timeout-"));
